let clients=[];try{const saved=JSON.parse(localStorage.getItem('brava-clients')||'[]');if(Array.isArray(saved))clients=saved}catch{}
const clientNav=document.createElement('button');clientNav.dataset.view='clients';clientNav.innerHTML='<b>♙</b> Clientes';document.querySelector('nav').append(clientNav);
const clientSection=document.createElement('section');clientSection.id='clients';clientSection.className='hidden';clientSection.innerHTML=`<div class="intro"><div><h1>Seus clientes, por perto.</h1><p>Organize os contatos de quem confia no seu trabalho.</p></div><button class="primary" id="addClient">Cadastrar pessoa +</button></div><div class="notice">Cadastros salvos apenas neste navegador. Não são sincronizados entre dispositivos.</div><label for="clientSearch">Buscar pessoas</label><input id="clientSearch" type="search" placeholder="Busque por nome, telefone ou e-mail"><p class="note" id="clientCount"></p><div id="clientList"></div><p id="clientStatus" role="status" aria-live="polite"></p>`;document.querySelector('main').insertBefore(clientSection,document.querySelector('footer'));
const clientDialog=document.createElement('dialog');clientDialog.id='clientDialog';clientDialog.innerHTML=`<button class="close" id="closeClient" aria-label="Fechar cadastro">×</button><span class="eyebrow">CADASTRO DE PESSOAS</span><h2 id="clientTitle">Novo cliente</h2><p>Os detalhes que deixam o atendimento mais próximo.</p><form id="clientForm"><label for="clientName">Nome completo *</label><input id="clientName" required maxlength="100" autocomplete="name" placeholder="Nome da pessoa"><label for="clientPhone">Telefone / WhatsApp *</label><input id="clientPhone" type="tel" required maxlength="22" autocomplete="tel" placeholder="(11) 99999-9999"><label for="clientEmail">E-mail</label><input id="clientEmail" type="email" maxlength="150" autocomplete="email" placeholder="nome@exemplo.com"><label for="clientBirthday">Data de nascimento</label><input id="clientBirthday" type="date"><p id="clientError" role="alert" style="color:#aa462c"></p><button class="primary wide" type="submit">Salvar cadastro</button></form>`;document.body.append(clientDialog);document.getElementById('clientBirthday').max=localDate();let editingClient=null;
const originalShowView=showView;showView=function(view){originalShowView(view);clientSection.classList.toggle('hidden',view!=='clients');if(view==='clients'){document.getElementById('breadcrumb').textContent='Clientes';renderClients()}};clientNav.onclick=()=>showView('clients');
function openClient(id=null){editingClient=id;document.getElementById('clientForm').reset();document.getElementById('clientError').textContent='';document.getElementById('clientTitle').textContent=id?'Editar cliente':'Novo cliente';const c=clients.find(c=>c.id===id);if(c){document.getElementById('clientName').value=c.name;document.getElementById('clientPhone').value=c.phone;document.getElementById('clientEmail').value=c.email;document.getElementById('clientBirthday').value=c.birthday||''}clientDialog.showModal()}
document.getElementById('addClient').onclick=()=>openClient();document.getElementById('closeClient').onclick=()=>clientDialog.close();document.getElementById('clientSearch').oninput=renderClients;
function renderClients(){const q=document.getElementById('clientSearch').value.trim().toLocaleLowerCase('pt-BR');const found=clients.filter(c=>[c.name,c.phone,c.email].some(v=>v.toLocaleLowerCase('pt-BR').includes(q))||q.replace(/\D/g,'').length>2&&c.phone.replace(/\D/g,'').includes(q.replace(/\D/g,''))).sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));document.getElementById('clientCount').textContent=found.length+' '+(found.length===1?'pessoa encontrada':'pessoas encontradas');document.getElementById('clientList').innerHTML=found.length?found.map(c=>`<article class="appointment clientCard"><div><h3>${escapeHTML(c.name)}</h3><p>${escapeHTML(c.phone)}${c.email?' · '+escapeHTML(c.email):''}</p>${c.birthday?'<p>Aniversário: '+c.birthday.split('-').reverse().join('/')+'</p>':''}</div><div class="clientActions"><button class="primary" data-book="${c.id}">Agendar</button><button class="textbtn" data-edit="${c.id}">Editar</button><button class="cancel" data-delete="${c.id}">Excluir</button></div></article>`).join(''):`<div class="empty"><h3>${q?'Nenhuma pessoa encontrada.':'Comece pelo primeiro cliente.'}</h3><p>${q?'Tente outro nome ou contato.':'Cadastre os contatos para agilizar seus próximos agendamentos.'}</p></div>`;document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openClient(b.dataset.edit));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>deleteClient(b.dataset.delete));document.querySelectorAll('[data-book]').forEach(b=>b.onclick=()=>{openBooking();document.getElementById('bookingClient').value=b.dataset.book;fillClient()})}
function persistClients(next){try{localStorage.setItem('brava-clients',JSON.stringify(next));clients=next;renderClients();updateClientOptions();return true}catch{document.getElementById('clientError').textContent='Não foi possível salvar. Verifique o espaço disponível e as permissões do navegador.';return false}}
document.getElementById('clientForm').onsubmit=e=>{e.preventDefault();const name=document.getElementById('clientName').value.trim(),phone=document.getElementById('clientPhone').value.trim(),email=document.getElementById('clientEmail').value.trim(),birthday=document.getElementById('clientBirthday').value;const digits=phone.replace(/\D/g,'');let error='';if(name.length<2)error='Informe um nome com pelo menos 2 caracteres.';else if(digits.length<10||digits.length>15)error='Informe um telefone válido com DDD (10 a 15 dígitos).';else if(clients.some(c=>c.id!==editingClient&&c.phone.replace(/\D/g,'')===digits))error='Este telefone já está cadastrado. Busque a pessoa para editar os dados.';else if(birthday>localDate())error='A data de nascimento não pode estar no futuro.';document.getElementById('clientError').textContent=error;if(error)return;const c={id:editingClient||crypto.randomUUID(),name,phone,email,birthday};const next=editingClient?clients.map(old=>old.id===editingClient?c:old):[...clients,c];if(persistClients(next)){clientDialog.close();document.getElementById('clientStatus').textContent='Cadastro salvo com sucesso.'}};
function deleteClient(id){const c=clients.find(c=>c.id===id);if(c&&confirm('Excluir o cadastro de '+c.name+'? Os agendamentos existentes serão mantidos.')){if(persistClients(clients.filter(c=>c.id!==id)))document.getElementById('clientStatus').textContent='Cadastro excluído.'}}
const bookingSelect=document.createElement('div');bookingSelect.innerHTML='<label for="bookingClient">Cliente cadastrado</label><select id="bookingClient"><option value="">Informar nome manualmente</option></select>';document.getElementById('form').insertBefore(bookingSelect,document.getElementById('form').firstChild);function updateClientOptions(){const select=document.getElementById('bookingClient'),selected=select.value;select.innerHTML='<option value="">Informar nome manualmente</option>'+[...clients].sort((a,b)=>a.name.localeCompare(b.name,'pt-BR')).map(c=>`<option value="${c.id}">${escapeHTML(c.name)} · ${escapeHTML(c.phone)}</option>`).join('');if(clients.some(c=>c.id===selected))select.value=selected;else select.value=''}function fillClient(){const c=clients.find(c=>c.id===document.getElementById('bookingClient').value);const name=document.getElementById('name');name.readOnly=!!c;name.value=c?c.name:''}document.getElementById('bookingClient').onchange=fillClient;const originalOpenBooking=openBooking;openBooking=function(i=0,barber='Rafael'){updateClientOptions();document.getElementById('bookingClient').value='';document.getElementById('name').readOnly=false;document.getElementById('name').value='';originalOpenBooking(i,barber)};updateClientOptions();renderClients();
